// Build full 400-location list
let allLocations = rawLocations.map(loc => ({
  id: `${loc.code.toLowerCase()}-${loc.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
  name: loc.name,
  country: loc.country,
  countryCode: loc.code,
  type: loc.type || 'destination',
  coordinates: { lat: loc.lat, lng: loc.lng },
  category: loc.cat || ['Destinations'],
  description: loc.desc,
  image: loc.img,
  rating: +(4.7 + Math.random() * 0.3).toFixed(1),
  toursCount: Math.floor(10 + Math.random() * 25),
  hotelsCount: Math.floor(25 + Math.random() * 70),
  startingPrice: loc.price,
  featured: !!loc.featured,
}))

remainingCountriesData.forEach(({ country, code, items }) => {
  items.forEach(item => {
    allLocations.push({
      id: `${code.toLowerCase()}-${item.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      name: item.name,
      country,
      countryCode: code,
      type: item.type || 'destination',
      coordinates: { lat: item.lat, lng: item.lng },
      category: item.cat || ['Destinations'],
      description: item.desc,
      image: item.img,
      rating: +(4.7 + Math.random() * 0.3).toFixed(1),
      toursCount: Math.floor(10 + Math.random() * 25),
      hotelsCount: Math.floor(25 + Math.random() * 70),
      startingPrice: item.price,
      featured: !!item.featured,
    })
  })
})

// Fill ids and ensure unique slugs
allLocations = allLocations.map((loc) => {
  const slug = `${loc.countryCode.toLowerCase()}-${loc.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`
  return {
    ...loc,
    id: loc.id || slug,
    slug: loc.slug || slug,
    rating: loc.rating || 4.9,
    toursCount: loc.toursCount || 15,
    hotelsCount: loc.hotelsCount || 40,
  }
})

console.log(`Total Curated Locations generated: ${allLocations.length}`)

// Generate JS output for frontend
const frontendJsContent = `// Auto-generated Curated Global Travel Exploration Dataset (400 Locations across 20 Countries)
export const COUNTRIES_LIST = ${JSON.stringify(COUNTRIES_LIST, null, 2)}

export const CATEGORIES_LIST = ${JSON.stringify(CATEGORIES_LIST, null, 2)}

export const EXPLORE_LOCATIONS = ${JSON.stringify(allLocations, null, 2)}

export default EXPLORE_LOCATIONS
`

// Paths
const frontendDestPath = path.resolve(__dirname, '../../../frontend/src/data/exploreDestinations.js')
const backendDestPath = path.resolve(__dirname, '../data/exploreLocations.json')

// Ensure dirs
fs.mkdirSync(path.dirname(frontendDestPath), { recursive: true })
fs.mkdirSync(path.dirname(backendDestPath), { recursive: true })

fs.writeFileSync(frontendDestPath, frontendJsContent, 'utf-8')
fs.writeFileSync(backendDestPath, JSON.stringify(allLocations, null, 2), 'utf-8')

console.log('Saved to frontend:', frontendDestPath)
console.log('Saved to backend:', backendDestPath)
